$cmd=[System.Collections.Generic.List[object]]::new(); $heads=@('编号','核实项','测试操作','预期结果','实际结果','判断和影响','完整测试路径','证据截图'); $cols=@('A','B','C','D','E','F','G','H'); $width=@(12,28,40,42,58,58,75,110); $colors=@{'已通过'='217568';'未通过'='AC3B3B';'存疑'='95651C'}
