function O([string[]]$a){& officecli @a;if($LASTEXITCODE-ne 0){throw 'officecli failed'}}; O @('create',$report); O @('set',$report,'/Sheet1','--prop','name=已通过'); O @('add',$report,'/','--type','sheet','--prop','name=未通过'); O @('add',$report,'/','--type','sheet','--prop','name=存疑'); O @('batch',$report,'--input',$input,'--stop-on-error'); O @('close',$report); $report
